head.script:
// https://inswave01.atlassian.net/browse/WAEA-1215
// ===== 리턴 값 출력 영역 (body_bottom.xml inline 복사) =====
scwin.btn_clear_onclick = function (e) {
    tbx_return.setValue("");
};

scwin.setReturnValue = function (strValue) {
    tbx_return.setValue(tbx_return.getValue() + strValue);
    tbx_return.setValue(tbx_return.getValue() + "\n");
};



scwin.onpageload = function () {
};



// 메소드 호출 직후 화면에 만들어진 레이어 상태를 읽는다.
//  진행 팝업창 : #___processbar2_i  /  확인창 : #gridDownLoadLayer  /  화면 모달 : #_modal
//  세 레이어 모두 다운로드가 끝나면 감춰지므로 호출 직후에 읽는다.
scwin.getLayerState = function () {
    let fnVisible = function (sSelector) {
        let objNode = document.querySelector(sSelector);
        return ((objNode !== null && objNode.style.display !== "none") ? "표시됨" : "표시 안 됨");
    };

    return "확인창 : " + fnVisible("#gridDownLoadLayer")
        + "  /  진행 팝업창 : " + fnVisible("#___processbar2_i")
        + "  /  화면 모달 : " + fnVisible("#_modal");
};



// [A] 정상 : showProcess 를 true 로, showConfirm 을 true 로 전달한다.
scwin.btn_normal_onclick = function () {
    target1.advancedExcelDownload({
        "fileName" : "fail_showConfirm_A",
        "extension" : "xlsx",
        "showProcess" : true,
        "showConfirm" : true
    });

    scwin.setReturnValue("[A] showProcess=true + showConfirm=true");
    scwin.setReturnValue(scwin.getLayerState());
};



// [B] 결함 : showProcess 를 false 로 함께 전달한다.
scwin.btn_fail_onclick = function () {
    target1.advancedExcelDownload({
        "fileName" : "fail_showConfirm_B",
        "extension" : "xlsx",
        "showProcess" : false,
        "showConfirm" : true
    });

    scwin.setReturnValue("[B] showProcess=false + showConfirm=true");
    scwin.setReturnValue(scwin.getLayerState());
};
